def _inbound_delivery_transfer_id(
    *,
    peer_fp: str,
    delivery_id: str,
    blob: str,
    delivery_name: str,
    delivery_rel_path: str,
    delivery_kind: str,
) -> str:
    """Build a collision-free inbound ledger key for one logical delivery.

    Legacy peers have no stable delivery nonce.  They retain a peer-scoped
    content + presentation-contract key; FILE_COMMIT-capable peers are
    required to supply the nonce.  Binding the sanitized name/path/kind keeps
    two intentional legacy deliveries of identical bytes from overwriting one
    ledger row, while a retransmission of the same legacy intent still
    coalesces.  It cannot provide modern exactly-once semantics (there is no
    sender nonce), but it removes every distinction the legacy wire actually
    exposes from the collision domain.
    """

    if _valid_delivery_id(delivery_id):
        return f"in:{peer_fp}:{delivery_id}"
    presentation_contract = json.dumps(
        [
            str(delivery_name),
            str(delivery_rel_path),
            str(delivery_kind),
        ],
        ensure_ascii=False,
        separators=(",", ":"),
    ).encode("utf-8")
    presentation_digest = hashlib.sha256(
        b"OL/legacy-inbound-presentation/v1\0" + presentation_contract
    ).hexdigest()[:32]
    return f"in:legacy:{peer_fp}:{blob}:{presentation_digest}"


def _incoming_delivery_contract_matches(
    incoming: "IncomingFile",
    *,
    peer_fp: str,
    delivery_id: str,
    delivery_name: str,
    delivery_rel_path: str,
    delivery_kind: str,
) -> bool:
    """Match an authenticated retry to the exact active delivery intent."""

    return (
        incoming.peer_fp == peer_fp
        and incoming.delivery_id == delivery_id
        and (incoming.delivery_name or incoming.name) == delivery_name
        and incoming.delivery_rel_path == delivery_rel_path
        and incoming.delivery_kind == delivery_kind
    )


def _validate_file_commit_receipt(
    receipt: dict,
    *,
    offer_id: str,
    blob: str,
    size: int,
    mode: str,
    delivery_id: str,
    delivery_name: str,
    delivery_rel_path: str,
    delivery_kind: str,
) -> dict:
    """Validate an authenticated-channel FILE_COMMIT without ambiguity.

    Channel AEAD authenticates the peer; these exact bindings prevent a valid
    receipt for another offer, blob, mode, or byte count from being crossed
    into this transfer.  A positive receipt is accepted only when the receiver
    explicitly attests durable storage and the exact offered BLAKE3.
    """

    if not isinstance(receipt, dict) or receipt.get("t") != "FILE_COMMIT":
        raise ReceiverCommitError("receiver returned no file commit receipt")
    version = receipt.get("receipt_version")
    if isinstance(version, bool) or version != FILE_COMMIT_RECEIPT_VERSION:
        raise ReceiverCommitError("receiver returned an unsupported file commit receipt")
    exact = {
        "of": str(offer_id),
        "blob": str(blob),
        "size": int(size),
        "mode": str(mode),
        "delivery_id": str(delivery_id),
        "delivery_name": str(delivery_name),
        "delivery_rel_path": str(delivery_rel_path),
        "delivery_kind": str(delivery_kind),
    }
    for field_name, expected in exact.items():
        actual = receipt.get(field_name)
        if field_name == "size" and isinstance(actual, bool):
            actual = None
        if actual != expected:
            raise ReceiverCommitError(f"crossed file commit receipt: {field_name} mismatch")
    ok = receipt.get("ok")
    if not isinstance(ok, bool):
        raise ReceiverCommitError("file commit receipt has invalid ok flag")
    retryable = receipt.get("retryable", False)
    if not isinstance(retryable, bool):
        raise ReceiverCommitError("file commit receipt has invalid retryable flag")
    committed_bytes = receipt.get("committed_bytes")
    if isinstance(committed_bytes, bool) or not isinstance(committed_bytes, int):
        raise ReceiverCommitError("file commit receipt has invalid byte count")
    if not ok:
        reason = str(receipt.get("reason") or "receiver_commit_failed")[:160]
        raise ReceiverCommitError(
            f"receiver file commit failed: {reason}",
            retryable=retryable,
        )
    if receipt.get("durable") is not True:
        raise ReceiverCommitError("receiver did not attest durable file commit")
    if committed_bytes != int(size):
        raise ReceiverCommitError("receiver file commit byte count mismatch")
    if receipt.get("verified_hash") != str(blob):
        raise ReceiverCommitError("receiver file commit hash mismatch")
    return dict(receipt)


def _channel_supports_file_commit_receipt(channel: object) -> bool:
    caps = getattr(channel, "peer_caps", None) or {}
    return FILE_COMMIT_RECEIPT_V1 in set(normalize_caps(caps.get("features") or ()))


def _file_commit_identity(path: Path) -> dict[str, int]:
    st = Path(path).stat()
    return {
        "size": int(st.st_size),
        "mtime_ns": int(st.st_mtime_ns),
        "ctime_ns": int(st.st_ctime_ns),
        "dev": int(getattr(st, "st_dev", 0) or 0),
        "ino": int(getattr(st, "st_ino", 0) or 0),
    }


def _fsync_parent_directory(path: Path) -> None:
    """Durably publish a file's directory entry where the OS exposes it."""

    if os.name == "nt":
        # Python exposes no documented Windows directory-fsync contract.
        # Critical namespace commits therefore perform their actual rename via
        # MoveFileExW(MOVEFILE_WRITE_THROUGH) in namespace_durability.
        return
    flags = os.O_RDONLY | int(getattr(os, "O_DIRECTORY", 0))
    fd = os.open(str(Path(path).parent), flags)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def _fsync_directory_chain(directory: Path, *, stop: Path) -> None:
    """Flush a created directory and every ancestor through ``stop``."""

    if os.name == "nt":
        return
    current = Path(directory).resolve()
    boundary = Path(stop).resolve()
    current.relative_to(boundary)
    flags = os.O_RDONLY | int(getattr(os, "O_DIRECTORY", 0))
    while True:
        fd = os.open(str(current), flags)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)
        if current == boundary:
            break
        current = current.parent


def _durable_commit_path(path: Path) -> dict[str, int]:
    """Flush file data and its directory entry, then capture stable identity."""

    resolved = Path(path)
    # Windows' CRT rejects fsync on a read-only descriptor (EBADF), even
    # though POSIX permits it. Receiver-owned inbox files are writable, so use
    # a read/write descriptor for one portable durable flush boundary.
    with open(resolved, "r+b") as committed:
        os.fsync(committed.fileno())
    _fsync_parent_directory(resolved)
    return _file_commit_identity(resolved)


def _verify_staged_file(
    path: Path,
    *,
    expected_blob: str,
    expected_size: int,
) -> dict[str, int]:
    """Whole-file verify and flush the exact staging inode.

    Rolling network hashers prove what arrived over the channel, not what is
    currently stored.  This second pass is the commit proof and detects local
    mutation, short writes, and pathname replacement before publication.
    """

    staged = Path(path)
    try:
        before_path = staged.lstat()
    except OSError as exc:
        raise OSError("receiver staging path is unavailable") from exc
    if stat.S_ISLNK(before_path.st_mode) or not stat.S_ISREG(before_path.st_mode):
        raise OSError("receiver staging path is not a regular file")
    with open(staged, "r+b") as committed:
        before = os.fstat(committed.fileno())
        if int(getattr(before_path, "st_dev", 0) or 0) != int(
            getattr(before, "st_dev", 0) or 0
        ) or int(getattr(before_path, "st_ino", 0) or 0) != int(getattr(before, "st_ino", 0) or 0):
            raise OSError("receiver staging path changed while opening")
        if int(before.st_size) != int(expected_size):
            raise OSError("receiver staging size changed before commit")
        committed.seek(0)
        digest = blake3.blake3()
        observed = 0
        while True:
            block = committed.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
            observed += len(block)
        after = os.fstat(committed.fileno())
        try:
            after_path = staged.lstat()
        except OSError as exc:
            raise OSError("receiver staging path disappeared during verification") from exc
        stable_fields = ("st_size", "st_mtime_ns", "st_ctime_ns", "st_dev", "st_ino")
        if any(getattr(before, key, 0) != getattr(after, key, 0) for key in stable_fields):
            raise OSError("receiver staging identity changed during verification")
        if (
            stat.S_ISLNK(after_path.st_mode)
            or not stat.S_ISREG(after_path.st_mode)
            or int(getattr(after_path, "st_dev", 0) or 0) != int(getattr(after, "st_dev", 0) or 0)
            or int(getattr(after_path, "st_ino", 0) or 0) != int(getattr(after, "st_ino", 0) or 0)
        ):
            raise OSError("receiver staging path changed during verification")
        if observed != int(expected_size) or digest.hexdigest() != str(expected_blob):
            raise OSError("receiver staging whole-file integrity failure")
        os.fsync(committed.fileno())
        durable = os.fstat(committed.fileno())
        identity = {
            "size": int(durable.st_size),
            "mtime_ns": int(durable.st_mtime_ns),
            "ctime_ns": int(durable.st_ctime_ns),
            "dev": int(getattr(durable, "st_dev", 0) or 0),
            "ino": int(getattr(durable, "st_ino", 0) or 0),
        }
    _fsync_parent_directory(staged)
    path_identity = _file_commit_identity(staged)
    if any(path_identity[key] != identity[key] for key in ("size", "mtime_ns", "dev", "ino")):
        raise OSError("receiver staging changed after durable verification")
    return path_identity


def _publish_verified_staging(
    staging_path: Path,
    final_path: Path,
    *,
    expected_blob: str,
    expected_size: int,
    verified_identity: dict[str, int] | None = None,
) -> dict[str, int]:
    """Verify a private staging inode and publish it without overwriting.

    POSIX uses an atomic no-replace hard link. Windows uses the actual rename
    operation with ``MOVEFILE_WRITE_THROUGH`` so the final namespace change,
    not merely the file contents, crosses the durable boundary. Failing closed
    is preferable to a rename that can overwrite a concurrent user file or to
    a visible partial copy.
    """

    staging = Path(staging_path)
    final = Path(final_path)
    if verified_identity is None:
        verified_identity = _verify_staged_file(
            staging,
            expected_blob=expected_blob,
            expected_size=expected_size,
        )
    else:
        verified_identity = {
            key: int(verified_identity[key])
            for key in ("size", "mtime_ns", "ctime_ns", "dev", "ino")
        }
        if _file_commit_identity(staging) != verified_identity:
            raise OSError("receiver staging changed after prepared verification")
    if staging.resolve() == final.resolve():
        _fsync_parent_directory(final)
        return verified_identity
    final.parent.mkdir(parents=True, exist_ok=True)
    try:
        staging_link_remains = publish_file_noreplace(staging, final)
    except FileExistsError:
        raise OSError("receiver destination appeared during atomic publish") from None
    except OSError as exc:
        raise OSError("receiver filesystem cannot atomically publish staging file") from exc
    try:
        try:
            _fsync_directory_chain(final.parent, stop=inbox_dir())
        except ValueError:
            # Library/tests may publish outside the configured inbox. The
            # leaf directory is still the relevant durable boundary there.
            _fsync_parent_directory(final)
        published = _file_commit_identity(final)
        if (
            published["size"] != int(expected_size)
            or published["dev"] != verified_identity["dev"]
            or published["ino"] != verified_identity["ino"]
            or published["mtime_ns"] != verified_identity["mtime_ns"]
        ):
            raise OSError("receiver published identity does not match verified staging")
        if staging_link_remains:
            staging.unlink()
            _fsync_parent_directory(staging)
        return published
    except Exception:
        with contextlib.suppress(OSError):
            final.unlink()
            _fsync_parent_directory(final)
        raise


def _publish_directory_noreplace(source: Path, destination: Path) -> None:
    """Atomically publish a directory without replacing any destination.

    POSIX ``rename`` may replace a concurrently-created empty directory, so
    it is never an acceptable fallback here. Windows uses a write-through,
    no-replace ``MoveFileExW`` operation. Linux uses
    renameat2(RENAME_NOREPLACE); platforms without an equivalent primitive
    fail closed and leave staging intact for the caller's retry/cleanup policy.
    """

    source = Path(source)
    destination = Path(destination)
    if source.parent.resolve() != destination.parent.resolve():
        raise OSError("atomic directory publication requires one parent")
    if os.name == "nt":
        try:
            publish_windows_path_noreplace(source, destination)
        except OSError as exc:
            if os.path.lexists(destination):
                raise FileExistsError(
                    "folder archive destination appeared during publication"
                ) from exc
            raise
        return
    if not sys.platform.startswith("linux"):
        raise OSError("filesystem has no supported atomic directory no-replace primitive")

    import ctypes
    import errno

    libc = ctypes.CDLL(None, use_errno=True)
    renameat2 = getattr(libc, "renameat2", None)
    if renameat2 is None:
        raise OSError(
            errno.ENOTSUP,
            "renameat2(RENAME_NOREPLACE) is unavailable",
        )
    renameat2.argtypes = [
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    ]
    renameat2.restype = ctypes.c_int
    at_fdcwd = -100
    rename_noreplace = 1
    result = renameat2(
        at_fdcwd,
        os.fsencode(source),
        at_fdcwd,
        os.fsencode(destination),
        rename_noreplace,
    )
    if result == 0:
        return
    error_number = ctypes.get_errno()
    if error_number in (errno.EEXIST, errno.ENOTEMPTY):
        raise FileExistsError(
            error_number,
            "folder archive destination appeared during publication",
            str(destination),
        )
    raise OSError(
        error_number,
        os.strerror(error_number),
        str(destination),
    )


def _open_private_incoming_staging(
    *,
    blob: str,
    delivery_id: str,
) -> tuple[Path, IO[bytes]]:
    root = inbox_dir().resolve()
    staging_root = root / INCOMING_STAGING_DIR
    staging_root.mkdir(mode=0o700, parents=True, exist_ok=True)
    if os.name != "nt":
        os.chmod(staging_root, 0o700)
        _fsync_directory_chain(staging_root, stop=root)
    nonce = delivery_id if _valid_delivery_id(delivery_id) else secrets.token_hex(16)
    for _attempt in range(32):
        candidate = staging_root / f"{blob[:16]}-{nonce}-{secrets.token_hex(8)}.part"
        try:
            handle = open(candidate, "x+b")
            return candidate, handle
        except FileExistsError:
            continue
    raise OSError("could not allocate a private incoming staging file")


def _hash_open_file(handle: IO[bytes], *, read_size: int = 4 * 1024 * 1024) -> str:
    """Hash one already-open file object without resolving its pathname again."""

    if read_size <= 0:
        raise ValueError("read_size must be positive")
    handle.seek(0)
    digest = blake3.blake3()
    while True:
        block = handle.read(read_size)
        if not block:
            break
        digest.update(block)
    handle.seek(0)
    return digest.hexdigest()


def _windows_open_file_identity(fd: int) -> tuple[str, int]:
    """Return ``(volume:file-id, NT-change-time-ns)`` for one CRT fd.

    ``Path.stat().st_ctime`` is creation time on Windows, not the NTFS change
    time. The latter is what invalidates a cached hash after an in-place,
    same-size rewrite whose last-write timestamp was restored.
    """

    if os.name != "nt":
        return "", 0
    try:
        import ctypes
        import msvcrt
        from ctypes import wintypes

        class _FileBasicInfo(ctypes.Structure):
            _fields_ = [
                ("creation_time", ctypes.c_longlong),
                ("last_access_time", ctypes.c_longlong),
                ("last_write_time", ctypes.c_longlong),
                ("change_time", ctypes.c_longlong),
                ("file_attributes", wintypes.DWORD),
            ]

        class _FileId128(ctypes.Structure):
            _fields_ = [("identifier", ctypes.c_ubyte * 16)]

        class _FileIdInfo(ctypes.Structure):
            _fields_ = [
                ("volume_serial_number", ctypes.c_ulonglong),
                ("file_id", _FileId128),
            ]

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        get_info = kernel32.GetFileInformationByHandleEx
        get_info.argtypes = [
            wintypes.HANDLE,
            ctypes.c_int,
            ctypes.c_void_p,
            wintypes.DWORD,
        ]
        get_info.restype = wintypes.BOOL
        os_handle = msvcrt.get_osfhandle(int(fd))
        if os_handle == -1:
            return "", 0
        basic = _FileBasicInfo()
        file_id = _FileIdInfo()
        if not get_info(
            wintypes.HANDLE(os_handle),
            0,  # FileBasicInfo
            ctypes.byref(basic),
            ctypes.sizeof(basic),
        ):
            return "", 0
        if not get_info(
            wintypes.HANDLE(os_handle),
            18,  # FileIdInfo
            ctypes.byref(file_id),
            ctypes.sizeof(file_id),
        ):
            return "", 0
        identifier = bytes(file_id.file_id.identifier).hex()
        stable_id = f"{int(file_id.volume_serial_number):016x}:{identifier}"
        # NT LARGE_INTEGER timestamps are 100-ns ticks since 1601. Keeping the
        # epoch is harmless; only exact equality is used.
        return stable_id, int(basic.change_time) * 100
    except (ImportError, OSError, TypeError, ValueError, AttributeError):
        return "", 0


@contextlib.contextmanager
def _open_binary_file_no_follow(path: Path) -> Iterator[BinaryIO]:
    """Open one regular-file candidate without following its final link.

    Windows additionally denies write/delete sharing for the lifetime of the
    descriptor, so the identity proven before a scan/send cannot be renamed or
    modified underneath that operation. POSIX uses ``O_NOFOLLOW`` and the
    caller's before/after inode + ctime checks to detect mutation.
    """

    candidate = Path(path)
    if os.name != "nt":
        flags = os.O_RDONLY | int(getattr(os, "O_CLOEXEC", 0))
        flags |= int(getattr(os, "O_NOFOLLOW", 0))
        fd = os.open(candidate, flags)
    else:
        import ctypes
        import msvcrt
        from ctypes import wintypes

        create_file = ctypes.windll.kernel32.CreateFileW
        create_file.argtypes = (
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.LPVOID,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.HANDLE,
        )
        create_file.restype = wintypes.HANDLE
        handle = create_file(
            str(candidate),
            0x80000000,  # GENERIC_READ
            0x00000001,  # FILE_SHARE_READ (deny write/delete sharing)
            None,
            3,  # OPEN_EXISTING
            (
                0x00000080  # FILE_ATTRIBUTE_NORMAL
                | 0x00200000  # FILE_FLAG_OPEN_REPARSE_POINT
                | 0x08000000  # FILE_FLAG_SEQUENTIAL_SCAN
            ),
            None,
        )
        invalid_handle = ctypes.c_void_p(-1).value
        if handle == invalid_handle:
            raise ctypes.WinError()
        try:
            fd = msvcrt.open_osfhandle(
                int(handle),
                os.O_RDONLY | int(getattr(os, "O_BINARY", 0)),
            )
        except Exception:
            ctypes.windll.kernel32.CloseHandle(handle)
            raise
    file_handle = os.fdopen(fd, "rb")
    try:
        yield file_handle
    finally:
        file_handle.close()


def _zip_central_directory_declaration(
    handle: IO[bytes],
    *,
    size: int,
) -> tuple[int, int]:
    """Read EOCD/ZIP64 bounds from the bound archive descriptor.

    The caller owns ``handle``. Reusing it for preflight, ``ZipFile`` reads,
    and final attestation prevents a pathname swap from presenting different
    archives at different validation stages.
    """

    size = int(size)
    if size < 22:
        raise ValueError("ZIP end-of-central-directory record is missing")
    tail_size = min(size, 22 + 65_535)
    handle.seek(size - tail_size)
    tail = handle.read(tail_size)
    marker = tail.rfind(b"PK\x05\x06")
    if marker < 0 or marker + 22 > len(tail):
        raise ValueError("ZIP end-of-central-directory record is missing")
    eocd = tail[marker : marker + 22]
    comment_size = int.from_bytes(eocd[20:22], "little")
    if marker + 22 + comment_size != len(tail):
        raise ValueError("ZIP end-of-central-directory record is malformed")
    disk_number = int.from_bytes(eocd[4:6], "little")
    central_disk = int.from_bytes(eocd[6:8], "little")
    disk_entries = int.from_bytes(eocd[8:10], "little")
    total_entries = int.from_bytes(eocd[10:12], "little")
    central_size = int.from_bytes(eocd[12:16], "little")
    if disk_number != 0 or central_disk != 0:
        raise ValueError("multi-disk ZIP archives are unsupported")
    if total_entries != 0xFFFF and central_size != 0xFFFFFFFF:
        if disk_entries != total_entries:
            raise ValueError("multi-disk ZIP archives are unsupported")
        return total_entries, central_size

    absolute_eocd = size - tail_size + marker
    locator_offset = absolute_eocd - 20
    if locator_offset < 0:
        raise ValueError("ZIP64 locator is missing")
    handle.seek(locator_offset)
    locator = handle.read(20)
    if len(locator) != 20 or locator[:4] != b"PK\x06\x07":
        raise ValueError("ZIP64 locator is missing")
    zip64_disk = int.from_bytes(locator[4:8], "little")
    zip64_offset = int.from_bytes(locator[8:16], "little")
    disk_count = int.from_bytes(locator[16:20], "little")
    if zip64_disk != 0 or disk_count != 1:
        raise ValueError("multi-disk ZIP64 archives are unsupported")
    if zip64_offset < 0 or zip64_offset + 56 > size:
        raise ValueError("ZIP64 end record is outside the archive")
    handle.seek(zip64_offset)
    zip64 = handle.read(56)
    if len(zip64) != 56 or zip64[:4] != b"PK\x06\x06":
        raise ValueError("ZIP64 end-of-central-directory record is missing")
    if int.from_bytes(zip64[16:20], "little") != 0 or int.from_bytes(zip64[20:24], "little") != 0:
        raise ValueError("multi-disk ZIP64 archives are unsupported")
    zip64_disk_entries = int.from_bytes(zip64[24:32], "little")
    zip64_total_entries = int.from_bytes(zip64[32:40], "little")
    if zip64_disk_entries != zip64_total_entries:
        raise ValueError("multi-disk ZIP64 archives are unsupported")
    return zip64_total_entries, int.from_bytes(zip64[40:48], "little")


def _should_build_cdc_offer(
    *,
    size: int,
    intent,
    existing_metadata: dict | None = None,
) -> tuple[bool, str]:
    """Decide whether a live send should pay CDC indexing cost.

    CDC is excellent when it skips enough bytes, but Python CDC is much slower
    than the fast stream path for first-time large media. Native CDC changes
    that tradeoff: large files can advertise chunk knowledge quickly, so the
    peer can skip anything it already has or source it from the trusted mesh.
    """

    if int(size) == 0:
        # CDC manifests require positive, contiguous ranges. The canonical
        # stream path already represents an empty file as one EOF chunk and
        # verifies the BLAKE3(empty) commit without inventing a zero-length
        # manifest entry that receivers correctly reject.
        return False, "empty_file_stream"
    if not getattr(intent, "can_offer_cdc", False):
        return False, "peer_does_not_support_cdc"
    md = existing_metadata or {}
    previous_mode = str(md.get("actual_method") or md.get("planned_wire_mode") or md.get("mode") or "")
    if previous_mode in {"file_cdc", "cdc", "swarm_cdc"}:
        return True, "resume_existing_cdc_transfer"
    if int(size) <= CDC_AUTO_INDEX_MAX_BYTES:
        return True, "small_enough_for_python_cdc"
    native = native_cdc_status()
    if native.available:
        return True, f"native_cdc_fast_lane:{native.engine}"
    return False, "large_file_fast_lane_until_native_cdc"


def _stream_transfer_profile(size: int) -> dict[str, int]:
    """Choose a safe high-throughput baseline stream profile.

    The goal is to fill modern Wi-Fi/Ethernet pipes without turning One Link
    into a RAM vacuum. Larger files get larger chunks and a bounded in-flight
    byte window; small files keep low latency and small allocations.
    """

    size = max(0, int(size))
    if size >= 2 * 1024 * 1024 * 1024:
        chunk_size = STREAM_MAX_CHUNK_SIZE
    elif size >= 512 * 1024 * 1024:
        chunk_size = 2 * 1024 * 1024
    elif size >= 64 * 1024 * 1024:
        chunk_size = 1024 * 1024
    else:
        chunk_size = STREAM_MIN_CHUNK_SIZE
    target = min(
        STREAM_PIPELINE_TARGET_BYTES,
        max(chunk_size, size if size > 0 else chunk_size),
    )
    window_chunks = max(1, min(STREAM_PIPELINE_MAX_CHUNKS, target // chunk_size))
    return {
        "chunk_size": int(chunk_size),
        "window_chunks": int(window_chunks),
        "window_bytes": int(window_chunks * chunk_size),
    }


def _align_cdc_pipeline_profile(
    profile: dict[str, Any],
    chunks: Iterable[Chunk],
    *,
    size: int,
    fresh_content: bool,
) -> dict[str, Any]:
    """Translate a byte-budgeted profile onto the published CDC manifest.

    The transfer brain plans in stream-sized chunks, while coherence-field
    ratchet cadence can intentionally publish much smaller fixed chunks.  A
    scheduler that copies only the planned *chunk count* silently collapses
    its in-flight byte budget (for example, four 250 kB chunks instead of four
    1 MiB chunks).  On a high-RTT path that turns one whole-file transfer into
    hundreds of avoidable ACK flights.

    Use the largest published chunk as the scheduler's accounting unit and
    preserve the brain's bounded byte budget.  The fresh-content warm start is
    still capped at four nominal large-file chunks (eight for small files), so
    this changes neither the memory bound nor the conservative first-flight
    policy; it only makes their units truthful.
    """

    aligned = dict(profile)
    nominal_chunk_size = max(1, int(aligned.get("chunk_size") or CHUNK_SIZE))
    nominal_window_chunks = max(
        1,
        int(aligned.get("window_chunks") or 1),
    )
    requested_window_bytes = max(
        nominal_chunk_size,
        int(aligned.get("window_bytes") or nominal_window_chunks * nominal_chunk_size),
    )
    manifest_chunk_size = max(
        (max(1, int(chunk.size)) for chunk in chunks),
        default=nominal_chunk_size,
    )
    target_window_bytes = requested_window_bytes
    warm_start_clamped = False
    if fresh_content:
        safe_nominal_chunks = 4 if int(size) >= 64 * 1024 * 1024 else 8
        safe_window_bytes = safe_nominal_chunks * nominal_chunk_size
        if target_window_bytes > safe_window_bytes:
            target_window_bytes = safe_window_bytes
            warm_start_clamped = True

    window_chunks = max(
        1,
        min(
            STREAM_PIPELINE_MAX_CHUNKS,
            target_window_bytes // manifest_chunk_size,
        ),
    )
    aligned.update(
        {
            "chunk_size": manifest_chunk_size,
            "window_chunks": int(window_chunks),
            "window_bytes": int(window_chunks * manifest_chunk_size),
            "nominal_chunk_size": nominal_chunk_size,
            "requested_window_bytes": requested_window_bytes,
            # AIMD growth advances in the original stream profile's byte unit,
            # not one potentially tiny coherence-cadence chunk per clean RTT.
            "growth_step_bytes": nominal_chunk_size,
            "manifest_window_aligned": manifest_chunk_size != nominal_chunk_size,
        }
    )
    if warm_start_clamped:
        reason = str(aligned.get("reason") or "adaptive")
        aligned["reason"] = reason + "_fresh_content_warm_start"
    return aligned


def _bound_native_stream_profile(
    profile: dict[str, Any],
    *,
    max_chunk_plaintext_len: int,
) -> dict[str, Any]:
    """Clamp an adaptive stream profile to the native AEAD envelope limit.

    The transfer brain is transport-agnostic and can legitimately choose
    multi-MiB stream chunks.  ``NativeTransferSession`` deliberately accepts
    at most ``MAX_CHUNK_PLAINTEXT_LEN`` bytes in one encrypted record.  Keep
    the original in-flight byte budget where possible by increasing the
    bounded chunk count, then rewrite every derived profile field together so
    the scheduler, read loop, progress totals, and diagnostic metadata all
    describe the same wire shape.
    """

    limit = max(1, int(max_chunk_plaintext_len))
    original_chunk_size = max(1, int(profile.get("chunk_size") or 1))
    original_window_chunks = max(1, int(profile.get("window_chunks") or 1))
    original_window_bytes = max(
        original_chunk_size,
        int(profile.get("window_bytes") or original_window_chunks * original_chunk_size),
    )
    chunk_size = min(original_chunk_size, limit)
    window_chunks = max(
        1,
        min(
            STREAM_PIPELINE_MAX_CHUNKS,
            (original_window_bytes + chunk_size - 1) // chunk_size,
        ),
    )
    return {
        **profile,
        "chunk_size": chunk_size,
        "window_chunks": window_chunks,
        "window_bytes": window_chunks * chunk_size,
        "native_chunk_max_bytes": limit,
        "native_chunk_size_capped": original_chunk_size > limit,
    }


def _tau_for_transfer_status(status: str) -> Optional[float]:
    """Map a transfer status label to a coarse τ_c observation in [0, 1].

    Used by D23 field-state writes from `_update_transfer`. The mapping
    is intentionally simple — the EWMA smooths noise across many
    observations, so individual status -> τ mappings just need to be
    monotone in "transfer healthiness."

    Returns None for status values where we have no signal (queued,
    waiting, etc.) so the caller skips the write.
    """
    s = (status or "").lower()
    # Terminal success states — strong positive signal.
    if s in ("done", "completed", "complete", "success", "finished"):
        return 0.95
    # Receiver-confirmed but not yet acknowledged — still positive.
    if s in ("acked", "delivered", "received"):
        return 0.85
    # In-flight states — neutral.
    if s in ("sending", "in_progress", "uploading", "downloading"):
        return 0.55
    # Soft errors / retry-able.
    if s in ("paused", "retrying", "stalled"):
        return 0.35
    # Hard failures — strong negative signal.
    if s in ("failed", "aborted", "rejected", "error", "timeout"):
        return 0.05
    return None


def _final_stream_ack_deadline(size: int) -> float:
    """Grace period for old receivers that cache chunks before final ACK."""

    size = max(0, int(size))
    cache_grace = size / FILE_FINAL_ACK_BYTES_PER_S if size else 0.0
    return float(min(
        FILE_SEND_TOTAL_DEADLINE_S,
        max(FILE_ACK_DEADLINE_S, FILE_FINAL_ACK_MIN_GRACE_S, cache_grace),
    ))


def _inter_chunk_ack_deadline(window_bytes: int) -> float:
    """Per-ACK deadline that scales with the in-flight window.

    Under load the receiver can stall draining its inbox while GC,
    state-store writes, or BLAKE3 verify take longer than expected.
    A fixed 30 s deadline (FILE_ACK_DEADLINE_S) makes 256 MiB+ transfers
    fail intermittently in real-network stress tests — the bytes get
    there but the ACK round-trip slips past 30 s.

    Scale with the window's drain time at the conservative 2 MiB/s
    floor, with FILE_ACK_DEADLINE_S as the lower bound and 120 s as
    the upper bound so we don't go past the final-ACK grace.
    """
    window_bytes = max(0, int(window_bytes))
    if window_bytes <= 0:
        return FILE_ACK_DEADLINE_S
    drain_s = window_bytes / FILE_FINAL_ACK_BYTES_PER_S
    return float(min(
        FILE_FINAL_ACK_MIN_GRACE_S,
        max(FILE_ACK_DEADLINE_S, drain_s),
    ))


def _version_at_least(version: str | None, major: int, minor: int, patch: int) -> bool:
    if not version:
        return False
    try:
        nums = []
        for part in str(version).strip().lstrip("v").split(".")[:3]:
            digits = "".join(ch for ch in part if ch.isdigit())
            nums.append(int(digits or 0))
        while len(nums) < 3:
            nums.append(0)
        return tuple(nums[:3]) >= (major, minor, patch)
    except Exception:
        return False


def _fast_fixed_chunk_size_for_peer(
    peer_version: str | None,
    *,
    size: int = 0,
    peer_features: list[str] | tuple[str, ...] | set[str] | None = None,
) -> int:
    """Largest fixed-manifest chunk this peer can safely parse.

    v0.12.5 receivers accept up to STREAM_MAX_CHUNK_SIZE in FILE_OFFER
    manifests. Older receivers clamp CDC-ish offers around 512 KiB, so we use
    the classic 256 KiB chunk when version is unknown/older to preserve
    zero-chunk repeat sends instead of silently falling back to streaming.
    """

    features = set(normalize_caps(peer_features or ()))
    modern_peer = (
        _version_at_least(peer_version, 0, 12, 5)
        or FILE_CDC_BINARY_FRAME in features
        or FILE_SWARM in features
    )
    if modern_peer:
        size = max(0, int(size or 0))
        if size >= 2 * 1024 * 1024 * 1024:
            return STREAM_MAX_CHUNK_SIZE
        if size >= 512 * 1024 * 1024:
            return 2 * 1024 * 1024
        return FAST_FIXED_CHUNK_SIZE
    return CDC_MAX_CHUNK_BYTES


def _encode_binary_frame(header: dict, data: bytes) -> bytes:
    """Encrypted-channel plaintext for binary payload frames.

    The channel still encrypts/authenticates the whole bytestring. This
    format only removes JSON/base64 from the plaintext payload:

        b"OLB1" + header_len:u32be + compact_json_header + raw_bytes
    """

    head = encode_msg(header)
    if len(head) > BINARY_FRAME_HEADER_MAX:
        raise ValueError(f"binary frame header too large: {len(head)}")
    return BINARY_FRAME_MAGIC + len(head).to_bytes(4, "big") + head + data


def _decode_binary_frame(payload: bytes) -> dict:
    if not payload.startswith(BINARY_FRAME_MAGIC):
        raise ValueError("not a One Link binary frame")
    if len(payload) < len(BINARY_FRAME_MAGIC) + 4:
        raise ValueError("binary frame header truncated")
    pos = len(BINARY_FRAME_MAGIC)
    n = int.from_bytes(payload[pos:pos + 4], "big")
    if n <= 0 or n > BINARY_FRAME_HEADER_MAX:
        raise ValueError(f"invalid binary frame header length: {n}")
    start = pos + 4
    end = start + n
    if end > len(payload):
        raise ValueError("binary frame header exceeds payload")
    msg = decode_msg(payload[start:end])
    msg["_binary_data"] = payload[end:]
    return msg


def _delivery_backoff_ms(attempts: int) -> int:
    attempts = max(1, int(attempts))
    delay_s = min(TRANSFER_RETRY_MAX_S, TRANSFER_RETRY_BASE_S * (2 ** (attempts - 1)))
    return int(delay_s * 1000)


def _delivery_backoff_ms_for_error(attempts: int, error: str) -> int:
    """Self-healing retry policy for durable file sends.

    Peer-offline rows should back off quietly. Route/session errors while a
    peer is visible are different: they often mean stale address, stale TCP, or
    peer startup churn, so we retry quickly for a bounded window instead of
    making the user wait behind exponential backoff.
    """
    msg = str(error).lower()
    route_markers = (
        "handshake timed out",
        "peer not responsive",
        "connection reset",
        "connection aborted",
        "broken pipe",
        "winerror 10053",
        "winerror 10054",
    )
    if attempts <= 12 and any(marker in msg for marker in route_markers):
        return 5_000
    return _delivery_backoff_ms(attempts)

# Capabilities this build advertises in CAPS messages.
# v0.5.4 bumps to OL1.2: CAPS optionally includes `share_rdz` so paired
# devices auto-inherit each other's rendezvous URL list. Older OL1.1
# peers ignore the field — strict-forward-compat.
PROTOCOL_VERSION = "OL1.2"
CAPS_FEATURES: list[str] = [
    # v0.20.7 (security audit C4 + H14): advertise the full
    # LOCAL_CAPABILITIES set including `double_ratchet_v1`. The
    # activation path was implemented in v0.7.2 (channel.py
    # note_caps_sent / note_caps_received / maybe_activate_ratchet)
    # but the cap was filtered out of advertised CAPS, leaving every
    # channel on the static AEAD keys derived once at handshake — so
    # captured ciphertext from a stolen long-term key stayed
    # decryptable forever and "block = cryptographic cutoff" was
    # fiction. The v0.7.2 ratchet activation regression suite
    # (test_channel_ratchet_v082.py + test_double_ratchet_v072.py)
    # is green; advertising the cap lets both sides activate and
    # delivers the forward-secrecy + post-compromise-security
    # guarantees that SECURITY.md §T3 commits to.
    *advertised_capabilities(),
    "audit",
    "fts",
    "trust",
    "trust_sync_v1",
    "rdz_inherit",  # advertises that we'll inherit rdz urls from peers
]
# v0.5.4: cap on how many URLs we'll embed in CAPS or accept from a
# peer. Defends against a malicious peer flooding us with junk URLs
# during pairing. Each inherited URL is also bound by state.set_rendezvous_urls
# validation which rejects non-http(s).
MAX_SHARED_RENDEZVOUS_URLS = 16
PRESENCE_STATES = frozenset({"online", "away", "dnd", "invisible", "offline"})

# Living Presence wire-message vocabulary. The receive-loop dispatch
# branches on these strings to route into _dispatch_living_presence_message.
_LIVING_PRESENCE_WIRE_TYPES = frozenset({
    "CALL_INVITE",
    "CALL_ACCEPT",
    "CALL_DECLINE",
    "CALL_END",
    "CALL_RESUME_OFFER",
    "CALL_ICE",
    "CALL_SDP_OFFER",
    "CALL_SDP_ANSWER",
    "CALL_FRAME_ATTEST",
    "RECORDING_REQUEST",
    "RECORDING_GRANT",
    "RECORDING_DECLINE",
    "RECORDING_STOP",
        "CAPSULE_OFFER",
        "CAPSULE_CHUNK",
        "CAPSULE_COMPLETE",
        "CAPSULE_RECEIPT",
    })
_TRUST_SYNC_WIRE_TYPE = "PEER_VERIFY_NOTICE"

# Async-capsule transport is deliberately tighter than the generic message
# path: offers expire, aggregate buffered audio is byte-capped, and no sender
# can occupy every inbound slot.  A durable receipt is the only event that
# clears the sender outbox.
CAPSULE_RECEIPT = "CAPSULE_RECEIPT"
CAPSULE_INBOUND_TTL_S = 180.0
CAPSULE_INBOUND_MAX = 16
CAPSULE_INBOUND_PER_PEER_MAX = 4
CAPSULE_INBOUND_BYTES_MAX = 64 * 1024 * 1024
CAPSULE_INBOUND_BYTES_PER_PEER_MAX = 32 * 1024 * 1024
CAPSULE_COMPLETED_REPLAY_MAX = 512
CAPSULE_DELIVERY_POLL_S = 15.0
CAPSULE_DELIVERY_BATCH = 4
CAPSULE_DELIVERY_FRAME_TIMEOUT_S = 40.0


def _build_caps(
    short_id: str,
    *,
    rendezvous_urls: list[str] | None = None,
    channel_bind: dict | None = None,
    presence: str | None = None,
    quic_port: int | None = None,
) -> dict:
    """Build a CAPS frame.

    `rendezvous_urls` (when provided + non-empty) becomes the
    `share_rdz` field — read by paired peers running v0.5.4+ to
    auto-inherit our rendezvous configuration. Pre-OL1.2 peers
    silently ignore it; we never put it on the wire if the local
    `share_rendezvous` setting is False.

    `quic_port` (when set) tells the peer where to dial QUIC for
    the Wave 2e/2f fast path. Previously only piggy-backed on
    ENDPOINT_UPDATE messages which arrive AFTER the channel
    handshake — meaning the first send_file to a freshly-opened
    channel always missed the QUIC fast path because the receiver's
    port wasn't yet known. Putting it in CAPS fixes that: a peer
    can dial QUIC on the very first chunk of the very first send,
    which is what unxfails ``test_send_file_stream_mode_actually_
    uses_quic_when_pinned``.
    """
    extra: dict = {}
    if rendezvous_urls:
        # Cap to a sane size — see MAX_SHARED_RENDEZVOUS_URLS comment.
        extra["share_rdz"] = list(rendezvous_urls)[:MAX_SHARED_RENDEZVOUS_URLS]
    if channel_bind:
        extra["channel_bind"] = dict(channel_bind)
    if presence:
        extra["presence"] = presence
    if isinstance(quic_port, int) and 0 < quic_port < 65536:
        extra["quic_port"] = int(quic_port)
    # v0.7.x: advertise the build version so peers can show "your other
    # device is on an older version" before a wire-format mismatch
    # turns into a cryptic InvalidTag. Old peers ignore unknown fields.
    try:
        from one_link import __version__ as _ol_ver
        extra["app_version"] = _ol_ver
    except (AttributeError, ImportError) as exc:
        report_best_effort_failure(
            log,
            "caps_version_metadata",
            exc,
            level=logging.DEBUG,
        )
    return make_msg(
        "CAPS",
        short_id,
        protocol=PROTOCOL_VERSION,
        features=list(CAPS_FEATURES),
        **extra,
    )


def _classify_address_regime(host: str) -> str:
    """v0.5.6: classify a remote host string as 'lan' (RFC 1918,
    loopback, link-local, IPv6 ULA, IPv6 link-local, carrier-grade
    NAT) or 'internet' (public). Pure string-based — same set the
    UI uses, kept consistent so server-side and client-side
    classification can't disagree.
    """
    if not host or not isinstance(host, str):
        return "internet"
    if host == "127.0.0.1" or host.startswith("127."):
        return "lan"
    if host == "::1":
        return "lan"
    if host.startswith("169.254."):
        return "lan"
    if host.startswith("10."):
        return "lan"
    if host.startswith("192.168."):
        return "lan"
    lower = host.lower()
    if lower.startswith("fe80:"):
        return "lan"
    if lower.startswith("fc") or lower.startswith("fd"):
        return "lan"
    # 172.16.0.0 – 172.31.255.255
    parts = host.split(".")
    if len(parts) >= 2 and parts[0] == "172":
        try:
            oct1 = int(parts[1])
            if 16 <= oct1 <= 31:
                return "lan"
        except ValueError:
            pass
    # 100.64.0.0/10 (carrier-grade NAT)
    if len(parts) >= 2 and parts[0] == "100":
        try:
            oct1 = int(parts[1])
            if 64 <= oct1 <= 127:
                return "lan"
        except ValueError:
            pass
    return "internet"


def _control_port_path() -> Path:
    return data_dir() / CONTROL_PORT_FILE


def _peer_port_path() -> Path:
    return data_dir() / PEER_PORT_FILE


def _daemon_lock_path() -> Path:
    return data_dir() / DAEMON_LOCK_FILE


def _read_runtime_ascii_scalar(path: Path, *, max_bytes: int = 64) -> str:
    """Read a tiny runtime hint without following aliases or buffering a file.

    Port/PID files are pre-authentication hints. They never establish trust,
    and an authenticated control exchange validates every port before use, but
    their parser still must not follow a junction/symlink or call ``read_text``
    on an attacker-replaced multi-gigabyte file. Bind the read to one regular
    file identity and cap it before decoding.
    """

    candidate = Path(path)
    before = candidate.lstat()
    attrs = int(getattr(before, "st_file_attributes", 0) or 0)
    reparse = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode) or bool(attrs & reparse):
        raise OSError("runtime hint is not a regular non-reparse file")
    flags = (
        os.O_RDONLY
        | int(getattr(os, "O_CLOEXEC", 0))
        | int(getattr(os, "O_BINARY", 0))
        | int(getattr(os, "O_NOFOLLOW", 0))
    )
    fd = os.open(str(candidate), flags)
    try:
        opened = os.fstat(fd)
        if not stat.S_ISREG(opened.st_mode):
            raise OSError("runtime hint changed type while opening")
        if (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino):
            raise OSError("runtime hint changed while opening")
        raw = os.read(fd, max(1, int(max_bytes)) + 1)
    finally:
        os.close(fd)
    if len(raw) > max_bytes:
        raise OSError("runtime hint exceeds byte limit")
    return raw.decode("ascii", errors="strict").strip()


def _atomic_replace(
    temporary: str | os.PathLike[str],
    target: str | os.PathLike[str],
    *,
    attempts: int = 12,
) -> None:
    """``os.replace`` that survives Windows' transient sharing violations.

    A POSIX ``rename(2)`` over an existing entry always succeeds. Windows does
    not work that way: any process holding either path open WITHOUT
    ``FILE_SHARE_DELETE`` makes the rename fail, and on a real machine that
    happens constantly for a file that was created milliseconds ago -- Defender
    and every other scanner, indexer, or backup agent opens new files to inspect
    them. The rename fails with ERROR_ACCESS_DENIED (5) or
    ERROR_SHARING_VIOLATION (32) and the operation is lost.

    This is not hypothetical. The daemon CRASHED ON STARTUP with

        PermissionError: [WinError 5] Access is denied:
        '...\\data\\.control.port.9076.<hex>.tmp'

    raised out of the port-file publish, because that publish had no tolerance
    for a condition Windows produces routinely. A user with antivirus installed
    would see One Link simply fail to start, intermittently and for no reason
    they could act on.

    Retrying is the correct remedy rather than a workaround: the condition is
    transient by nature (the scanner closes the handle), and a bounded retry
    changes nothing about the ATOMICITY the callers rely on -- the replace
    either happened or it did not. POSIX keeps the single unretried call, so a
    genuine error there still surfaces immediately, and a non-transient Windows
    error (anything other than 5/32) is re-raised at once instead of being
    slept over.
    """

    if os.name != "nt":
        os.replace(temporary, target)
        return
    delay = 0.005
    for attempt in range(max(1, attempts)):
        try:
            os.replace(temporary, target)
            return
        except PermissionError as exc:
            transient = getattr(exc, "winerror", None) in (5, 32)
            if not transient or attempt == max(1, attempts) - 1:
                raise
            time.sleep(delay)
            delay = min(delay * 2, 0.2)


EVENT_LOOP_STALL_WARN_SECONDS = 5.0
EVENT_LOOP_WATCHDOG_INTERVAL_SECONDS = 1.0


def _start_event_loop_watchdog(
    loop: asyncio.AbstractEventLoop,
    *,
    stall_seconds: float = EVENT_LOOP_STALL_WARN_SECONDS,
    interval: float = EVENT_LOOP_WATCHDOG_INTERVAL_SECONDS,
) -> threading.Event:
    """Log a stack trace whenever the event loop stops answering.

    A blocking call on the loop thread is invisible from outside and nearly
    invisible from inside: the OS keeps accepting connections on every
    listener the daemon opened, so the control plane and the UI look up and
    healthy while nothing is ever read from them. The daemon's own log says
    nothing at all, because the code that would log is not running.

    Diagnosing that from the outside costs whole CI runs and reduces to
    guesswork about which synchronous call is to blame. So the daemon names
    it itself: a plain thread pings the loop once a second, and if the ping
    is not acknowledged within ``stall_seconds`` it prints the loop thread's
    live stack -- the exact frame that is blocking. Costs one wakeup per
    second and stays silent on a healthy host.

    Returns the stop event, so a caller can retire the watchdog.
    """

    stop = threading.Event()
    loop_thread_id = threading.get_ident()

    def _watch() -> None:
        while not stop.is_set():
            acknowledged = threading.Event()
            try:
                loop.call_soon_threadsafe(acknowledged.set)
            except RuntimeError:
                return  # loop closed; the daemon is going away
            if not acknowledged.wait(stall_seconds):
                frame = sys._current_frames().get(loop_thread_id)
                where = (
                    "".join(traceback.format_stack(frame))
                    if frame is not None
                    else "<loop thread stack unavailable>"
                )
                log.warning(
                    "event loop has not answered for %.0fs -- something on the "
                    "loop thread is blocking. Listeners still accept "
                    "connections but no request can be served. Loop thread "
                    "stack:\n%s",
                    stall_seconds,
                    where,
                )
                # Wait for the loop to come back before probing again, so one
                # stall produces one report rather than a stream of them --
                # but keep checking the stop event, because a loop that never
                # answers again is precisely what shutdown looks like, and an
                # unbounded wait here would strand this thread forever.
                while not stop.is_set() and not acknowledged.wait(interval):
                    pass
            stop.wait(interval)

    threading.Thread(
        target=_watch,
        name="one-link-loop-watchdog",
        daemon=True,
    ).start()
    return stop


def _publish_runtime_ascii_scalar(path: Path, value: str, *, max_bytes: int = 64) -> None:
    """Atomically publish a bounded port/PID hint without following ``path``.

    Writing a well-known pathname with ``Path.write_text`` follows a pre-planted
    symlink and turns daemon startup into an arbitrary same-user file clobber.
    Write an exclusive sibling and atomically replace the directory entry; an
    existing link is replaced as an object, never traversed.
    """

    target = Path(path)
    text = str(value)
    if not text or text != text.strip():
        raise ValueError("runtime hint must be non-empty canonical text")
    try:
        payload = text.encode("ascii")
    except UnicodeEncodeError as exc:
        raise ValueError("runtime hint must be ASCII") from exc
    if len(payload) > max(1, int(max_bytes)):
        raise ValueError("runtime hint exceeds byte limit")
    target.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    temporary = target.with_name(f".{target.name}.{os.getpid()}.{secrets.token_hex(8)}.tmp")
    flags = (
        os.O_WRONLY
        | os.O_CREAT
        | os.O_EXCL
        | int(getattr(os, "O_CLOEXEC", 0))
        | int(getattr(os, "O_NOFOLLOW", 0))
    )
    fd: int | None = None
    try:
        fd = os.open(str(temporary), flags, 0o600)
        written = 0
        while written < len(payload):
            count = os.write(fd, payload[written:])
            if count <= 0:
                raise OSError("short write while publishing runtime hint")
            written += count
        os.fsync(fd)
        os.close(fd)
        fd = None
        _atomic_replace(temporary, target)
        if os.name != "nt":
            directory_fd = os.open(str(target.parent), os.O_RDONLY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
    finally:
        if fd is not None:
            with contextlib.suppress(OSError):
                os.close(fd)
        with contextlib.suppress(OSError):
            temporary.unlink()


def _open_daemon_lock_file(path: Path) -> BinaryIO:
    """Open/create the singleton lock without following links or hardlinks."""

    candidate = Path(path)
    candidate.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    if os.name != "nt":
        flags = (
            os.O_RDWR
            | os.O_CREAT
            | int(getattr(os, "O_CLOEXEC", 0))
            | int(getattr(os, "O_NOFOLLOW", 0))
        )
        fd = os.open(str(candidate), flags, 0o600)
        try:
            fchmod = getattr(os, "fchmod", None)
            if not callable(fchmod):
                raise OSError("descriptor permission hardening is unavailable")
            fchmod(fd, 0o600)
        except Exception:
            os.close(fd)
            raise
    else:
        import ctypes
        import msvcrt
        from ctypes import wintypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        create_file = kernel32.CreateFileW
        create_file.argtypes = (
            wintypes.LPCWSTR,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.LPVOID,
            wintypes.DWORD,
            wintypes.DWORD,
            wintypes.HANDLE,
        )
        create_file.restype = wintypes.HANDLE
        handle = create_file(
            str(candidate),
            0x80000000 | 0x40000000,  # GENERIC_READ | GENERIC_WRITE
            0x00000001 | 0x00000002,  # share read/write, deny delete/rename
            None,
            4,  # OPEN_ALWAYS
            0x00000080 | 0x00200000,  # NORMAL | OPEN_REPARSE_POINT
            None,
        )
        invalid_handle = ctypes.c_void_p(-1).value
        if handle == invalid_handle:
            raise ctypes.WinError(ctypes.get_last_error())
        try:
            fd = msvcrt.open_osfhandle(
                int(handle),
                os.O_RDWR | int(getattr(os, "O_BINARY", 0)),
            )
        except Exception:
            kernel32.CloseHandle(handle)
            raise

    try:
        opened = os.fstat(fd)
        path_stat = candidate.lstat()
        attrs = int(getattr(path_stat, "st_file_attributes", 0) or 0)
        reparse = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
        if (
            not stat.S_ISREG(opened.st_mode)
            or stat.S_ISLNK(path_stat.st_mode)
            or not stat.S_ISREG(path_stat.st_mode)
            or bool(attrs & reparse)
            or int(getattr(opened, "st_nlink", 1) or 1) != 1
            or (opened.st_dev, opened.st_ino) != (path_stat.st_dev, path_stat.st_ino)
        ):
            raise OSError("daemon lock is not one private regular file")
        return os.fdopen(fd, "r+b")
    except Exception:
        os.close(fd)
        raise


def _pid_is_alive(pid: int) -> bool:
    """Return True if the given OS PID is currently a live process.

    Cross-platform, stdlib-only. False positives are acceptable (we'll
    refuse to start), false negatives are not (we'd corrupt state).
    """
    if pid <= 0:
        return False
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
        STILL_ACTIVE = 259
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        handle = kernel32.OpenProcess(
            PROCESS_QUERY_LIMITED_INFORMATION, False, wintypes.DWORD(pid)
        )
        if not handle:
            err = ctypes.get_last_error()
            # ERROR_ACCESS_DENIED (5) means the PID exists but we can't
            # query it — treat as alive (safer to refuse to start).
            return err == 5
        try:
            exit_code = wintypes.DWORD()
            ok = kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code))
            if not ok:
                return True
            return exit_code.value == STILL_ACTIVE
        finally:
            kernel32.CloseHandle(handle)
    else:
        try:
            os.kill(pid, 0)
        except ProcessLookupError:
            return False
        except PermissionError:
            return True  # exists, owned by another user
        except OSError:
            return False
        return True


def _argv_is_one_link_daemon(argv: Iterable[str]) -> bool:
    """Return whether a process command line is a One Link daemon.

    A PID is not a durable process identity: operating systems routinely
    reuse it after the original process exits.  The daemon lock therefore
    must not treat a live PID alone as proof that another One Link daemon
    owns the lock file.
    """
    args = [str(arg).strip().strip('"').lower() for arg in argv if str(arg).strip()]
    if not args:
        return False

    # Source / editable installs: python -m one_link.cli daemon
    for idx in range(len(args) - 2):
        if (
            args[idx] == "-m"
            and args[idx + 1] in {"one_link", "one_link.cli"}
            and "daemon" in args[idx + 2 :]
        ):
            return True

    # Frozen distributions: one-link[.exe] daemon
    executable = Path(args[0]).name
    if executable.endswith(".exe"):
        executable = executable[:-4]
    return executable in {"one-link", "one_link"} and "daemon" in args[1:]


def _pid_matches_one_link_daemon(pid: int) -> bool:
    """Verify that ``pid`` is a One Link daemon for the current home.

    This is intentionally stronger than :func:`_pid_is_alive`.  A stale
    ``daemon.lock`` can outlive its process and its numeric PID can later be
    assigned to an unrelated application.  Refusing startup in that case
    leaves One Link permanently offline even though this process already
    acquired the authoritative OS file lock.

    The command line identifies One Link and the inherited
    ``ONE_LINK_HOME`` distinguishes concurrently running test/profile
    homes.  If process metadata is unavailable, an authenticated-by-shape
    local control response for the same PID and exact data home is accepted.
    """
    if pid <= 0:
        return False

    try:
        import psutil  # type: ignore

        proc = psutil.Process(pid)
        argv = proc.cmdline()
        if not _argv_is_one_link_daemon(argv):
            return False

        try:
            proc_env = proc.environ()
        except Exception as exc:
            log.debug(
                "process environment unavailable for pid=%d; requiring "
                "control-channel attestation: %s",
                pid,
                exc,
            )
        else:
            process_home = proc_env.get("ONE_LINK_HOME")
            current_home = os.environ.get("ONE_LINK_HOME")
            if bool(process_home) != bool(current_home):
                return False
            if process_home and current_home:
                process_data = (Path(process_home).expanduser() / "data").resolve()
                current_data = (Path(current_home).expanduser() / "data").resolve()
                return os.path.normcase(str(process_data)) == os.path.normcase(str(current_data))
            # Neither process has an override, so platformdirs resolves both
            # to the same per-user default home.
            return True
    except Exception as exc:
        # OS process inspection is advisory. Authenticated control IPC below
        # remains the authority when inspection is denied or unavailable.
        report_best_effort_failure(
            log,
            "daemon_process_inspection",
            exc,
            level=logging.DEBUG,
            interval_s=30.0,
        )

    # Process inspection can be denied by the OS.  In that case, require the
    # actual One Link control protocol to attest both PID and data home.
    ports: set[int] = set(_candidate_control_ports_for_pid(pid))
    with contextlib.suppress(Exception):
        port = int(_read_runtime_ascii_scalar(_control_port_path()))
        if port > 0:
            ports.add(port)
    expected_home = str(data_dir())
    for port in ports:
        status = query_control_status(port, timeout=0.5)
        if (
            status.get("ok") is True
            and int(status.get("pid") or 0) == pid
            and str(status.get("home") or "") == expected_home
        ):
            return True

    # The authoritative OS lock is already held by our caller. If process
    # metadata is unavailable and no One Link control endpoint corroborates
    # this PID, the file contents are stale evidence rather than ownership.
    # Treating an arbitrary live PID as a daemon permanently bricks startup
    # on systems without psutil and after normal PID reuse.
    return False


def _read_lock_pid() -> int | None:
    try:
        raw = _read_runtime_ascii_scalar(_daemon_lock_path())
        return int(raw) if raw else None
    except Exception:
        return None


def _runtime_port_paths() -> tuple[Path, ...]:
    """Files that describe a live daemon instance, not durable user data."""
    return (
        data_dir() / CONTROL_PORT_FILE,
        data_dir() / PEER_PORT_FILE,
        data_dir() / "server.port",
    )


def _clear_stale_runtime_files() -> None:
    """Remove dead daemon runtime hints without touching identity/state.

    These files are just pointers to a currently running process. If the
    process is gone, leaving them behind makes launchers and tests try a
    port that will never answer. That is exactly the class of "spins forever"
    failure a self-healing desktop app must not expose to users.
    """
    for p in (*_runtime_port_paths(), _daemon_lock_path()):
        with contextlib.suppress(OSError):
            p.unlink()


def _candidate_control_ports_for_pid(pid: int) -> list[int]:
    """Return localhost listen ports owned by ``pid``.

    This is a recovery path for launchers: if a stale helper removes
    ``control.port`` while the daemon is healthy, the app should repair the
    hint file instead of spinning or starting a duplicate daemon.
    """
    if pid <= 0:
        return []
    ports: set[int] = set()
    try:
        import psutil  # type: ignore
        proc = psutil.Process(pid)
        for conn in proc.net_connections(kind="tcp"):
            if getattr(conn, "status", "") != "LISTEN":
                continue
            laddr = getattr(conn, "laddr", None)
            port = getattr(laddr, "port", None)
            if port:
                ports.add(int(port))
        if ports:
            return sorted(ports)
    except Exception as exc:
        report_best_effort_failure(
            log,
            "pid_listen_port_inspection",
            exc,
            level=logging.DEBUG,
        )
    if os.name == "nt":
        try:
            argv = resolve_argv(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    (
                        "Get-NetTCPConnection -State Listen "
                        f"-OwningProcess {int(pid)} -ErrorAction SilentlyContinue | "
                        "Select-Object -ExpandProperty LocalPort"
                    ),
                ],
                system_tool=True,
            )
            out = subprocess.check_output(
                argv,
                stderr=subprocess.DEVNULL,
                text=True,
                timeout=5,
                # CREATE_NO_WINDOW — otherwise a conhost flashes every
                # call. This codepath is recovery-only but still hit.
                creationflags=hidden_creationflags(),
                cwd=str(Path(argv[0]).parent),
                env=trusted_process_env(),
                shell=False,
            )
            for line in out.splitlines():
                line = line.strip()
                if line.isdigit():
                    ports.add(int(line))
        except (OSError, subprocess.SubprocessError, ValueError) as exc:
            report_best_effort_failure(
                log,
                "windows_pid_listen_port_fallback",
                exc,
                level=logging.DEBUG,
            )
    return sorted(ports)


def _candidate_local_listen_ports() -> list[int]:
    ports: set[int] = set()
    try:
        import psutil  # type: ignore
        for conn in psutil.net_connections(kind="tcp"):
            if getattr(conn, "status", "") != "LISTEN":
                continue
            laddr = getattr(conn, "laddr", None)
            host = str(getattr(laddr, "ip", "") or "")
            port = getattr(laddr, "port", None)
            if port and host in ("", "0.0.0.0", "::", "127.0.0.1", "::1"):  # nosec B104
                ports.add(int(port))
        if ports:
            return sorted(ports)
    except Exception as exc:
        report_best_effort_failure(
            log,
            "local_listen_port_inspection",
            exc,
            level=logging.DEBUG,
        )
    if os.name == "nt":
        try:
            argv = resolve_argv(
                [
                    "powershell.exe",
                    "-NoProfile",
                    "-NonInteractive",
                    "-Command",
                    (
                        "Get-NetTCPConnection -State Listen "
                        "-ErrorAction SilentlyContinue | "
                        "Where-Object { $_.LocalAddress -in "
                        "@('127.0.0.1','0.0.0.0','::1','::') } | "
                        "Select-Object -ExpandProperty LocalPort"
                    ),
                ],
                system_tool=True,
            )
            out = subprocess.check_output(
                argv,
                stderr=subprocess.DEVNULL,
                text=True,
                timeout=5,
                creationflags=hidden_creationflags(),
                cwd=str(Path(argv[0]).parent),
                env=trusted_process_env(),
                shell=False,
            )
            for line in out.splitlines():
                line = line.strip()
                if line.isdigit():
                    ports.add(int(line))
        except (OSError, subprocess.SubprocessError, ValueError) as exc:
            report_best_effort_failure(
                log,
                "windows_local_listen_port_fallback",
                exc,
                level=logging.DEBUG,
            )
    return sorted(ports)


def _recover_control_port_from_live_pid() -> int | None:
    pid = _read_lock_pid()
    if pid is None or not _pid_is_alive(pid):
        return None
    candidates: list[int] = []
    candidates.extend(_candidate_control_ports_for_pid(pid))
    if not candidates:
        candidates.extend(_candidate_local_listen_ports())
    home = str(data_dir())
    for port in candidates:
        # query_control_status has a no-raise contract and returns an empty
        # mapping for an unreachable or unauthenticated candidate.
        status = query_control_status(port, timeout=0.75)
        if (
            status.get("ok") is True
            and (pid is None or int(status.get("pid") or 0) == int(pid))
            and str(status.get("home") or "") == home
        ):
            with contextlib.suppress(OSError):
                _publish_runtime_ascii_scalar(_control_port_path(), str(port))
            return int(port)
    return None


@dataclass
class IncomingFile:
    name: str
    size: int
    blob_hex: str
    out_path: Path
    # Writable binary file handle the receiver streams chunks into.
    # ``IO[bytes]`` covers both the builtins.open(...) result and any
    # custom binary writer we might inject in tests.
    handle: IO[bytes]
    # ``hasher`` is the blake3 Hasher instance running in parallel
    # with the write stream. blake3 doesn't ship PEP-561 stubs, so
    # the field is type-checked as ``_HasherProtocol`` (a small
    # nominal protocol the call sites need — update + hexdigest).
    # Required field — the construction site always supplies it.
    hasher: "_HasherProtocol"
    # Chunks land in ``out_path``, a private same-volume staging file.  The
    # user-visible collision-safe destination is not published until the
    # staging descriptor has been whole-file hashed and fsynced.
    final_path: Path | None = None
    delivery_id: str = ""
    delivery_name: str = ""
    delivery_rel_path: str = ""
    delivery_kind: str = "file"
    received: int = 0
    next_seq: int = 0
    cdc_chunks: list[dict] | None = None
    cdc_missing: set[int] | None = None
    cdc_parts: dict[int, bytes] | None = None
    # Indices of CDC chunks that have already been seeked-and-
    # written to ``out_path`` at their correct file offset during
    # this session. ``_finish_cdc_file`` skips re-writing these
    # (the bytes are already where they should be); only cache-
    # only chunks (received in a prior session, restored on
    # cross-restart resume) still need a write at finish time.
    cdc_streamed: set[int] = field(default_factory=set)
    # Number of CDC chunks committed since the last sidecar
    # ``touch()`` write. Debounces sidecar persistence so we don't
    # do a JSON round-trip on every chunk.
    cdc_chunks_since_touch: int = 0
    # Deferred chunk-availability records waiting to be batched
    # into a single SQLite transaction. The receive loop appends
    # to this list as chunks arrive; the per-64-chunk debounce
    # flush + the finish path commit them via
    # ``state.record_chunks_available_batch``. Replaces one
    # autocommit transaction per chunk with one per batch — for
    # a 1024-chunk 256 MiB transfer, that's 16 commits instead of
    # 1024.
    cdc_pending_state: list[dict] = field(default_factory=list)
    # Running total of bytes committed to disk for this transfer.
    # Maintained incrementally so the per-chunk progress callback
    # doesn't have to walk the entire manifest summing sizes
    # (which was an O(N) walk per chunk = O(N²) overall). Wave 2a+.
    cdc_done_bytes: int = 0
    # Number of CDC chunks committed since the last
    # ``_update_transfer`` broadcast. Same idea as the sidecar
    # touch debounce — surfaces transfer progress to the UI at
    # ~16 updates per file instead of N (where N can be 4000+).
    cdc_chunks_since_progress: int = 0
    transfer_id: str | None = None
    ack_batch_ids: list[str] = field(default_factory=list)
    # Authorization is transfer-scoped, not connection-scoped. Once the
    # accept-first gate has been cleared, reconnects must not turn the same
    # blob from the same peer back into a new prompt.
    acceptance_granted: bool = False
    # Authenticated owner + admission-ledger key. Optional defaults keep old
    # persisted/test fixtures readable; production construction always sets
    # both so another peer cannot spend or release this sender's reservation.
    peer_fp: str = ""
    reservation_id: str = ""
    cache_reservation_id: str = ""
    # The current FILE_OFFER request id is the nonce that binds the final
    # FILE_COMMIT receipt to this exact attempt. ``commit_waiters`` retains
    # every live retry channel while a CDC finalizer is hashing/fsyncing so a
    # fresh offer cannot redirect the old attempt's receipt (or vice versa).
    offer_id: str = ""
    commit_receipt_required: bool = False
    commit_waiters: dict[str, Any] = field(default_factory=dict)
    commit_progress_seq: int = 0
    finalizing: bool = False


class _HasherProtocol(Protocol):
    """Minimal interface IncomingFile needs from a streaming hasher.

    blake3.blake3() returns an instance that satisfies this contract.
    Pinned as a Protocol so we don't depend on blake3 shipping stubs
    and tests can substitute a stub without subclassing."""

    def update(self, data: bytes) -> None: ...

    def hexdigest(self) -> str: ...


class _PairHealth(TypedDict, total=False):
    """Per-peer health snapshot kept in ``Daemon._pair_health``.
    Keys are populated incrementally as PING / ACK / chunk-arrival
    events fire, so ``total=False``."""

    last_alive_ms: int
    latency_ewma_ms: float
    bandwidth_bps: float
    reliability: float
    best_route: str


@dataclass
class OutboundSession:
    peer_fp: str
    peer: Peer
    channel: ch.Channel
    lock: asyncio.Lock
    last_used: float
    messages_sent: int = 0
    # v0.5.6: which transport regime carried this session?
    #   "lan"      — direct TCP, peer.address is RFC-1918/loopback/etc.
    #   "internet" — direct TCP, peer.address is a public address
    #   "relay"    — went through the encrypted-relay fallback
    #   "unknown"  — pre-v0.5.6 session, regime not stamped
    regime: str = "unknown"
    # v0.6.x audit: when the regime is "relay", the inbound-pump task
    # that drains the relay WebSocket needs to be awaited on cleanup
    # so the per-session aiohttp ClientSession can flush+close before
    # the loop exits. Otherwise pytest under -W error::ResourceWarning
    # surfaces "Unclosed client session" warnings as test ends race
    # with task finally-blocks.
    relay_pump_task: asyncio.Task | None = None


def _harden_process_dumpability() -> None:
    """External audit 2026-05-18 ES-12: prevent coredumps / crash dumps
    from writing identity-key bytes to disk. Best-effort across OSes;
    every step is wrapped in try/except so a missing kernel feature or
    insufficient permission doesn't block daemon start.

    Coverage:
      - POSIX: setrlimit(RLIMIT_CORE, 0) so the kernel never writes
        a coredump for this process.
      - Linux: prctl(PR_SET_DUMPABLE, 0) so even if RLIMIT_CORE is
        bypassed, ptrace and /proc/<pid>/mem are blocked from peer
        processes (and the process is excluded from system-wide
        crash-dump capture).
      - macOS: setrlimit(RLIMIT_CORE, 0) is the main lever; the
        equivalent of PR_SET_DUMPABLE is a setuid-trickery special
        case that doesn't apply to user-mode daemons.
      - Windows: SetErrorMode(SEM_NOGPFAULTERRORBOX | SEM_FAILCRITICALERRORS)
        suppresses the Windows Error Reporting dump. Additionally
        SetProcessMitigationPolicy(ProcessExtensionPointDisablePolicy)
        blocks DLL-injection-based debugger attach (best-effort).
    """
    try:
        import resource  # POSIX only
        resource.setrlimit(resource.RLIMIT_CORE, (0, 0))  # type: ignore[attr-defined]  # POSIX-only
        log.info("hardened: RLIMIT_CORE=0 (no coredumps)")
    except (ImportError, OSError, ValueError) as e:
        # ImportError = Windows; OSError = permission/unsupported.
        log.debug("RLIMIT_CORE not set: %s", e)
    try:
        import ctypes
        # Linux: PR_SET_DUMPABLE = 4
        libc = ctypes.CDLL("libc.so.6", use_errno=True)
        rc = libc.prctl(4, 0, 0, 0, 0)
        if rc == 0:
            log.info("hardened: PR_SET_DUMPABLE=0 (no ptrace, no /proc/<pid>/mem)")
    except (OSError, AttributeError):
        # Not Linux, or libc not available; non-fatal.
        pass
    try:
        # Windows: suppress Windows Error Reporting crash dumps.
        import ctypes
        SEM_NOGPFAULTERRORBOX = 0x0002
        SEM_FAILCRITICALERRORS = 0x0001
        kernel32 = ctypes.windll.kernel32  # type: ignore[attr-defined]
        kernel32.SetErrorMode(SEM_NOGPFAULTERRORBOX | SEM_FAILCRITICALERRORS)
        log.info("hardened: Windows ErrorMode suppresses GP fault dumps")
    except (OSError, AttributeError):
        # Not Windows, or ctypes can't reach windll; non-fatal.
        pass


class Daemon:
    CALL_SIGNAL_SEND_TIMEOUT_S = 6.0
    TRUST_SYNC_SEND_TIMEOUT_S = 6.0
    CALL_PREINVITE_TTL_S = 30.0
    CALL_PREINVITE_CACHE_MAX = 64
    CALL_PREINVITE_CACHE_PER_PEER_MAX = 4

    def __init__(self, me: Identity):
        self.me = me
        # The localhost control socket is a privileged API, not a trust
        # boundary.  ``start()`` loads the private per-install credential
        # after acquiring the single-instance lock.  A random process
        # identity binds the authenticated control status to the HTTP proof
        # endpoint, closing stale/spoofed UI-port token theft races.
        self._control_secret: str | None = None
        self._control_instance_id = secrets.token_urlsafe(24)
        self._control_response_contexts: dict[
            asyncio.StreamWriter, control_ipc.ControlExchange
        ] = {}
        self._control_read_stash: dict[asyncio.StreamReader, bytes] = {}
        self._active_control_connections = 0
        self.discovery: Discovery | None = None
        self._peer_server: asyncio.base_events.Server | None = None
        self._control_server: asyncio.base_events.Server | None = None
        self._loop_watchdog_stop: threading.Event | None = None
        self._tail_subs: set[asyncio.StreamWriter] = set()
        self._incoming_files: dict[str, IncomingFile] = {}
        self._outbound_file_gates: dict[str, _OutboundFileGate] = {}
        # Bind in-flight folder blobs to the authenticated peer as well as
        # their content hash.  The same hash may legitimately be requested
        # from several peers at once; a global blob-only key lets one peer
        # overwrite or feed another peer's writer.
        self._incoming_blobs: dict[tuple[str, str, str, str], dict] = {}
        # 2026-05-22 audit Batch CC: centralised background-task set.
        # All fire-and-forget ``asyncio.create_task`` call sites
        # should route through ``self._track(coro)`` so the task
        # set is drainable in stop(). Without tracking, tasks leak
        # past shutdown and asyncio reports "Task was destroyed but
        # it is pending!". Each task auto-discards from the set on
        # completion via add_done_callback.
        self._background_tasks: set[asyncio.Task] = set()
        # Receiver-side resume: a small persistent sidecar per
        # in-progress CDC inbound transfer lets us survive a
        # daemon restart or a mid-transfer peer disconnect without
        # re-fetching chunks already in the cache. The registry is
        # populated from disk in start() and consulted by the
        # FILE_OFFER handler before allocating a fresh IncomingFile.
        self._resume_metadata_root = data_dir() / "transfer_resume"
        self._resume_registry: ResumeRegistry = ResumeRegistry(inbox_dir(),
            metadata_root=self._resume_metadata_root,
        )
        # A random, per-process lifecycle identity is persisted only after
        # this daemon owns the instance lock.  A matching durable clean-stop
        # marker lets the next process distinguish an intentional restart
        # from a crash without trusting a recycled PID or a stale marker.
        self._runtime_lifecycle: dict[str, int | str] | None = None
        # Wave 2d: QUIC server endpoint (None when the native crate
        # isn't installed). Brought up in start() via the Wave 2c
        # Identity bridge; published-as-port to paired peers via
        # the existing endpoint-announcement frame. accept-loop
        # task and per-peer outbound connection cache populate
        # below.
        # Native pyo3 endpoint (one_link_native) — mypy has no stub for it,
        # so Any is the honest type (lets its real methods type-check).
        self._quic_server_endpoint: "Any | None" = None
        self._quic_accept_task: asyncio.Task | None = None
        self._quic_local_port: int | None = None
        # peer_fp_hex -> native QUIC Connection (outbound).
        # Owned by daemon; closed in stop(). New entries appear
        # when send_file's QUIC path dials a peer that advertised
        # a quic port.
        self._quic_outbound: dict[str, Any] = {}  # native pyo3 QUIC conns (no stub)
        # Exact receiver-side commit evidence for chunks delivered over QUIC.
        # A response can be lost after the handler has durably advanced the
        # transfer.  The sender must then be able to replay the *same* request
        # (including across a WebRTC fallback) without decrypting/writing it a
        # second time or tripping the sequential ``seq`` guard.  Entries are
        # content-bound, peer-bound, and bounded as an LRU so this idempotency
        # window cannot become attacker-controlled unbounded memory.
        self._quic_chunk_commits: "OrderedDict[tuple[Any, ...], dict[str, Any]]" = OrderedDict()
        # peer_fp_hex -> advertised QUIC port (Wave 2d). Populated
        # by _handle_endpoint_update; consumed by the outbound
        # dial helper.
        self._quic_peer_ports: dict[str, int] = {}
        # Bounded ring of "silent degradation" events — moments
        # when a more-capable path (native transfer, QUIC, DR,
        # CDC) was advertised by both peers but the actual
        # transfer fell back to a less-capable path. Exposed via
        # the ``transfer_diagnostics`` control command so tests
        # can assert the fast path actually fired and operators
        # can monitor degradation rates instead of having to
        # grep through hours of WARNING-level logs. This is the
        # broader fix for the Wave 2f silent-fallback class of
        # bug (see commit `28e264d`).
        from collections import deque as _deque
        self._degradation_events: _deque[dict] = _deque(maxlen=512)
        # peer_fp_hex -> native QUIC Connection (inbound). Wave 2e.
        # Populated by the accept loop after binding the peer's
        # fingerprint via the recent-callback deque below.
        self._quic_inbound: dict[str, Any] = {}  # native pyo3 QUIC conns (no stub)
        # QUIC endpoint-advertisement healing. QUIC ports are
        # OS-assigned and can change on daemon restart. If a single
        # ENDPOINT_UPDATE is missed, the fast path used to stay dark
        # until a manual restart/pin. These timestamps throttle
        # reciprocal announcements so pinned peers converge again
        # automatically.
        self._quic_endpoint_reply_last_ms: dict[str, int] = {}
        # Bounded ring of recent is_paired callback hits:
        # (timestamp_ms, fingerprint_bytes). The accept loop uses
        # the most-recent entry to map an inbound Connection back
        # to its peer_fp. Native crate's accept doesn't yet
        # surface the peer fingerprint directly; this deque is
        # the workaround. Production-grade fix is to extend the
        # native API.
        from collections import deque as _deque
