        self._sovereignty_transition_lock = asyncio.Lock()
        self._rendezvous_lifecycle_lock = asyncio.Lock()
        self._update_check_network_lock = asyncio.Lock()
        self._lan_discovery_network_lock = asyncio.Lock()
        self._sovereignty_transition_target: str | None = None
        self._update_check_task: asyncio.Task | None = None
